and u.dept_id = #{currentDeptId}
and  and coalesce(c.valid_from,c.issued_date) <= #{asOfDate} and c.expires_on < #{asOfDate}
and  and coalesce(c.valid_from,c.issued_date) <= #{asOfDate} and c.expires_on between #{asOfDate} and date_add(#{asOfDate}, interval 30 day)
and  and coalesce(c.valid_from,c.issued_date) <= #{asOfDate} and c.expires_on <= date_add(#{asOfDate}, interval 30 day)
and  and coalesce(c.valid_from,c.issued_date) <= #{asOfDate} and c.expires_on > date_add(#{asOfDate}, interval 30 day)
and c.review_status='APPROVED' and coalesce(c.valid_from,c.issued_date) > #{asOfDate}
${params.dataScope}
order by case c.review_status when 'PENDING_REVIEW' then 0 else 1 end,
         c.expires_on, c.certificate_id desc

select  
where c.del_flag = '0' and c.review_status = 'APPROVED'
  and  and coalesce(c.valid_from,c.issued_date) <= #{asOfDate}
  and c.expires_on <= #{expiresThrough}
  and c.certificate_id > #{afterCertificateId}
  and (p.employee_status is null or p.employee_status <> '离职')
order by c.certificate_id
limit #{limit}

mapper.update:
update hr_employee_health_certificate
set current_flag = 'Y', update_by = #{updateBy}, update_time = sysdate(), version = version + 1
where certificate_id = #{certificateId} and user_id = #{userId}
  and review_status = 'APPROVED' and del_flag = '0' and current_flag is null
  and coalesce(valid_from,issued_date) <= #{asOfDate} and expires_on >= #{asOfDate}
